custom_css:
/*月光啊月光-烤冷面大王*/

/*适配大部分调整🌷🌷🌷自定义区即可*/


/* ====== 全局字体与变量 ====== */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fbold.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A700%3Bfont-display%3Aswap%3B%7D%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
  font-family: "KingHwaOldSong";
  font-weight: normal;
}

/* 英文专用 ZSFT-bo */
#send_textarea,
.message-content,
.bubble-content,
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  font-family: "ZSFT-bo", "KingHwaOldSong", sans-serif !important;
}


:root {
  /*🌷🌷🌷自定义区⬇️*/
  --输入框文字:"moonbeams";

  --面板背景: url("https://i.postimg.cc/9MF95fzK/IMG-5335.jpg");

  /* 气泡尺寸 */
  --上层气泡宽度: 104%;
  --下层气泡宽度: 105%;
  --中层宽度: 373px;
  --中层高度计算: calc(100% - 300px);

  /* 名字位置 */
  --名字上下: -3px;
  --名字左右: 20px;

  /* 楼层位置 */
  --楼层上下: 125%;
  --楼层左右: -70%;

  /* 计时器位置 */
  --计时器上下: 115%;
  --计时器左右: -55%;

  /* 字符位置 */
  --字符上下: 105%;
  --字符左右: -40%;

  /* 头像 */
  --头像显示位置: 50% 10%;
  --头像宽度: 153px;
  --头像高度: 153px;
  --头像位置上下: 86px;
  --头像位置左右: 163px;

  /* 头像框 */
  --头像框宽度: 154px;
  --头像框高度: 154px;
  --头像框位置上下: -1%;
  --头像框位置左右: -1%;

  /* user文字边距 */
  --user文字上边距: 60px;
  --user文字右边距: 3px;
  --user文字下边距: 0px;
  --user文字左边距: 1px;
  --user文字外上边距: 10px;
  --user文字外下边距: 20px;

  /* 首楼char文字边距 */
  --首楼char上边距: 0px;
  --首楼char右边距: 7px;
  --首楼char下边距: 0px;
  --首楼char左边距: 1px;
  --首楼char外上边距: 55px;
  --首楼char外下边距: 30px;

  /* char文字边距 */
  --char上边距: 0px;
  --char右边距: 7px;
  --char下边距: 0px;
  --char左边距: 1px;
  --char外上边距: 20px;
  --char外下边距: 30px;

  /* 思维链位置 */
  --思维链平移X: 120px;
  --思维链平移Y: -25px;

  /* 三个点+小铅笔位置 */
  --三点铅笔上下: 60px;
  --三点铅笔左右: 230px;

  /* 小铅笔展开位置 */
  --小铅笔上下: 65px;
  --小铅笔左右: -70px;

  /* 三个点展开位置 */
  --三点展开上下: 18%;
  --三点展开左右: -230px;

  /* 欢迎页助手消息 */
  --欢迎页助手消息: "我们好像在池塘的水底 从一个月亮走向另一个月亮。";

  /* 欢迎页助手头像 */
  --欢迎页头像显示位置: 50% 10%;
  --欢迎页头像宽度: 145px;
  --欢迎页头像高度: 145px;
  --欢迎页头像: url("https://i.postimg.cc/TwdyVbQ5/IMG-5297.jpg");

  /*🌷🌷🌷自定义区⬆️*/

  --字母m: url("https://i.postimg.cc/9Mhdvzbw/IMG-5326.png");
  --字母o: url("https://i.postimg.cc/Kjcn8VC6/IMG-5327.png");
  --字母n: url("https://i.postimg.cc/L5yjYDph/IMG-5328.png");
  --字母b: url("https://i.postimg.cc/jqvHFx7L/IMG-5329.png");
  --字母e: url("https://i.postimg.cc/m25QTmVW/IMG-5330.png");
  --字母a: url("https://i.postimg.cc/3wMmvWPb/IMG-5331.png");
  --字母s: url("https://i.postimg.cc/C17qX7d2/IMG-5332.png");
  --月亮图标: url("https://i.postimg.cc/Zq6ZLPcT/IMG-5319.png");
  --打勾图标: url("https://i.postimg.cc/2jtmpkSK/IMG-5365.png");

  --上层气泡: url("https://i.postimg.cc/J4NsVhsQ/IMG-5346.png");
  --中层气泡: url("https://i.postimg.cc/j2zSb8d9/IMG-5347.png");
  --下层气泡: url("https://i.postimg.cc/fRWTGfnZ/IMG-5348.png");

  --边框: url("https://i.postimg.cc/DfWS9qDN/IMG-5357.png");
  --背景图: url("https://i.postimg.cc/TwD7g1dm/IMG-5356.jpg");
  --头像框: url("https://i.postimg.cc/g0PL0QZT/IMG-5314.png");
  --欢迎页头像: url("https://i.postimg.cc/TwdyVbQ5/IMG-5297.jpg");
}


/*===顶栏部分===*/
#top-bar {
    position: fixed !important;
    top: 0;
    left: 0;
    width: 100%;
    height: 40px;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width:98%;
    height: 100%;
    background: #000 !important;
border: 2px solid #e3e8f0;
border-image: linear-gradient(45deg, #f8f9fa, #c5cde0, #e3e8f0, #c5cde0, #f8f9fa) 1;
box-shadow: 0 0 15px rgba(220, 228, 240, 0.7), inset 0 0 8px rgba(190, 200, 218, 0.4);
z-index: 7;
pointer-events: auto;
clip-path: polygon(
    0 0, 100% 0, 100% 100%, 0 100%,
    5% 0, 95% 0, 95% 100%, 5% 100%
);}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 8;
    pointer-events: none;
}







/*by墨千尾老师，图标替换*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}

#top-settings-holder .drawer { flex: 1; }

#top-settings-holder .drawer-icon {
    display: block;
    margin-top: 15px;
    background-color: transparent;
    border-radius: 0px !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 25px;
    height: 25px;
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover { transform: translateY(-1.5px); }

/* --- 顶栏九个图标替换（加补丁） --- */
.drawer-icon.fa-sliders { background-image: var(--字母m); }
.drawer-icon.fa-plug { background-image: var(--字母o); }
.drawer-icon.fa-font { background-image: var(--字母o); }
.drawer-icon.fa-book-atlas { background-image: var(--字母n); }
.drawer-icon.fa-user { background-image: var(--字母b); }
.drawer-icon.fa-image { background-image: var(--字母e); }
.drawer-icon.fa-cubes { background-image: var(--字母a); }

.drawer-icon.fa-face-smile { background-image: var(--字母m); }
.drawer-icon.fa-address-card { background-image: var(--字母s); }


#backgrounds-drawer-toggle .drawer-icon{
    background-image: var(--字母e) !important;
    transform: scale(1); 
}

#user-settings-button .drawer-icon {
    background-image: var(--字母b) !important;
    transform: scale(1); 
}

/* 展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--月亮图标) !important; 
    transform: scale(1.3); 
}



/*底栏*/
#send_form {

  min-height: 100px !important;
  height: auto !important;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  background-image: var(--边框);
  background-repeat: repeat !important;
  background-size: 100% 100% !important;
  background-position: center !important;
  border-radius: 9px !important;
  overflow: hidden !important;
}




#form_sheld {
  position: absolute;
  bottom: 10px; /* 调整上下 */
}

#send_form {
  width: 100%; /* 调整宽度 */
}

/* 最后一条消息与底栏间距 */
#chat {
  padding-bottom: 140px !important;
}

/* 输入长文本时底栏不挡正文by咩野 */
#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
  position: static;
}


#send_textarea {
  position: relative !important;
  top: -15px !important; 
  margin: 0 auto !important;
  border-radius: 6px !important;
  clip-path: none !important;
  background-color: #000 !important;
  border-color: transparent !important;
}


/* --- byNini老师，默认隐藏 QR 按钮容器，并设置平滑过渡 --- */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

/* --- 新增：修复空白弹窗，仅隐藏空白背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}



/* --- 底部按键图标替换 --- */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
    display: none !important;
}
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
    width: 20px !important;
    height: 30px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border-radius: 0px !important;
    opacity: 1 !important;}

#options_button,
#extensionsMenuButton{
    /* 位置调整 */
    position: relative !important;
    top: -10px !important;    /* 正数向下，负数向上 */
    left: 25px !important;  /* 正数向右，负数向左 */
}

#send_but,
#quick-reply-rocket-button ,#mes_stop i{
  /* 位置调整 */
    position: relative !important;
    top: -10px !important;    /* 正数向下，负数向上 */
    left: -25px !important;  /* 正数向右，负数向左 */
}


div#mes_continue.fa-fw.fa-solid.fa-arrow-right.interactable::before {
    /* 位置调整 */
    position: relative !important;
    top: -10px !important;    /* 正数向下，负数向上 */
    left: -25px !important;  /* 正数向右，负数向左 */
}



#options_button,
#extensionsMenuButton {
    background-image: var(--月亮图标) !important;
}

#send_but {
    background-image: var(--月亮图标) !important;
}

#quick-reply-rocket-button {
    background-image: var(--月亮图标) !important;
}

/* 输入框样式 */
#send_form #send_textarea {
    width: 80% !important;
    max-width: 80% !important;
    transform: scale(0.8) !important;
    transform-origin: center !important;
    border-radius: 6px !important;
    background-color: #3d3d3d !important;
    border: none !important;
}


/* ===== by墨千尾老师，输入框提示文字自定义 ===== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--输入框文字);
    color: #fff!important;
    position: absolute; 
    left: 55%;
    top: 0%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.4em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/*面板背景*/
.drawer-content {
    background:  var(--面板背景) center/cover fixed no-repeat;
}



/* 聊天气泡 */
.mes {
    width: 96% !important;
    max-width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    margin-top: 10px !important;
    margin-bottom: auto;
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0!important;
    box-shadow: none !important;
    padding-top: 220px !important;
    padding-bottom: 180px !important;
    padding-left: 3px !important;
    padding-right: 2px !important;



  background-image:
    var(--上层气泡),
        var(--下层气泡),
        var(--中层气泡);
   background-position:
  calc(50% + 2px) top,
  center bottom,
  calc(50% + 1px) 200px;

background-size:
  var(--上层气泡宽度) auto,
  var(--下层气泡宽度) auto,
  var(--中层宽度) var(--中层高度计算);

background-repeat:
  no-repeat,
  no-repeat,
  no-repeat;
}


/*🌷名字*/
.mes_block .ch_name {
  position: relative;
  top: var(--名字上下);
  left: var(--名字左右);
   max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 100; 
  font-size: 1.1em;
  font-weight: 300;
  letter-spacing: 0.9px;
  white-space: nowrap;
  transform: rotate(0deg); /* 旋转 */
  color: #fff !important; 
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
}

/*名字换行*/
.name_text {
  display: block !important;
  width: 90px !important;       /* 控制在多少像素处换行 */
  white-space: normal !important;
  word-break: break-all !important;
  overflow-wrap: break-word !important;
}



/* 三元素 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    position: absolute !important;
    z-index: 9 !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important; 
    width: 20px !important; 
    min-width: auto !important;
    height: auto !important;
    font-size: 10px !important; 
    color: #fff !important; 
    line-height: 1.1 !important;     
    padding: 0 !important;
    margin: 0 !important;
    background: none !important;
    border: none !important;
    opacity: 1;
    white-space: nowrap !important;
    pointer-events: none; 
    writing-mode: vertical-lr !important;
    text-orientation: upright !important;
}

/*楼层*/
.mes .mesIDDisplay {
  top: var(--楼层上下) !important;
  left: var(--楼层左右) !important;
}

/*计时器*/
.mes .mes_timer {
  top: var(--计时器上下) !important;
  left: var(--计时器左右) !important;
}

/*字符*/
.mes .tokenCounterDisplay {
  top: var(--字符上下) !important;
  left: var(--字符左右) !important;
}



/* 头像 */
.mes .avatar img {
  object-position: var(--头像显示位置) !important;
  width: var(--头像宽度) !important;
  height: var(--头像高度) !important;

  object-fit: cover !important;
  border-radius: 50% !important;
  box-shadow: none !important;
  position: relative;
  z-index: 2;
}

.mes .mesAvatarWrapper {
  position: absolute;
  top: var(--头像位置上下);
  left: var(--头像位置左右);
  width: auto;
  padding: 0;
}

.mes .mesAvatarWrapper .avatar {
  flex-basis: auto;
  display: flex;
  justify-content: center;
  position: relative;
  width: var(--头像宽度);
  height: var(--头像高度);
}

/* 头像框部分 */
.mes .avatar::before,
.mes .avatar::after {
  content: "";
  position: absolute;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
}

/*头像框*/
.mes .avatar::after {
  background-image: var(--头像框);
  width: var(--头像框宽度);
  height: var(--头像框高度);
  top: var(--头像框位置上下);
  left: var(--头像框位置左右);
  z-index: 4;
}





/* 文本框与下一个头像框隔开 */
.mes {
    margin-bottom: 3em !important; 
    clear: both !important; 
}


/*文字铺满by墨千尾老师*/
.mes_text {
    width: 100%;

/* 🌷user文字边距 */
    padding: var(--user文字上边距) var(--user文字右边距) var(--user文字下边距) var(--user文字左边距);
    margin: var(--user文字外上边距) 0px var(--user文字外下边距) 0px;
}



/*首楼char文字边距 */
.mes:first-of-type:not([is_user="true"]) .mes_text {
  width: 100%;

/*🌷首楼char文字边距 */
    padding: var(--首楼char上边距) var(--首楼char右边距) var(--首楼char下边距) var(--首楼char左边距);
    margin: var(--首楼char外上边距) 0px var(--首楼char外下边距) 0px;
}


/*char文本位置*/
.mes:not([is_user="true"]) .mes_text {
  width: 100%;

 /*🌷char文字边距 */
    padding: var(--char上边距) var(--char右边距) var(--char下边距) var(--char左边距);
    margin: var(--char外上边距) 0px var(--char外下边距) 0px;
}




/*——思维链——*/
/* 🌷思维链位置⬇️ */
.mes_reasoning_header {
  transform: translate(var(--思维链平移X), var(--思维链平移Y)) !important;
}

.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;
    --bottom-padding: 1rem;
    --left-padding: 0.1rem;
    --right-padding: 0.1rem;
    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0;
    backdrop-filter: none !important; 
    -webkit-backdrop-filter: none !important; 
    padding: 0 !important;
    margin-bottom: 0 !important;
    color: var(--reasoning-text) !important;
    font-size: 1em !important;
    display: inline-flex !important;
    align-items: center !important;
    transition: none !important; 
}
/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}
/*来自N老师*/
.mes_reasoning_header_title::before {
    content: '';
    display: inline-block;
    width: 60px;
    height: 60px;
    background-image: var(--月亮图标);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
}
.mes_reasoning_header_title {
    font-size: 0;
}



 /* 三个点+小铅笔部分
给你的按钮父层全开溢出可见 */
.mes_buttons,
.mes,
.block,
.message {
  overflow: visible !important;
  contain: unset !important;
  clip: unset !important;
}



.mes {
  position: relative !important;
}


.mes_buttons {
  position: absolute !important;

/*🌷三个点+小铅笔位置 */
  top: var(--三点铅笔上下) !important;  
  left: var(--三点铅笔左右) !important;   

  z-index: 9999 !important;
  padding: 0 !important;
  min-height: 36px;
  box-sizing: border-box;
  transform: rotate(0deg) !important;
  width: auto !important;
}

.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
